                            TopRated = false
                        },
                        new
                        {
                            Id = 23,
                            Author = "كيتلين شنايدرهان",
                            CategoryId = 3,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "لا تؤدّي كلُّ الطرق إلى النجاة، فأحيانًا ما تكون مجرّد بداية، كأغنيةٍ بعيدة تأتي من مكانٍ مجهول، ثم تعلو.. حتى تصير صراخًا يسكن الرأس.\nفي «تحليق إيكاروس» لا تقف الكارثة عند حدود بلدة صغيرة، بل تبدأ من داخلها؛ من رغبةٍ جارفةٍ في الخلاص، من حلمٍ بأن يصبح المرء ذو قيمة، ومن خطوةٍ واحدة نحو ضوء يبدو جميلًا، يعد بالأمل.. ويُخفي الاحتراق.\nولا تبدأ الحكاية بطفلٍ صغير يختفي دون أثر، أو بوحشٍ يخرج من الظلام، بل بشابٍّ.. يظن أن الخروج من البلدة هو النجاة، وأن الموسيقى هي الوسيلة المثلى لتحقيق هدفه.\nلكن بعض الأبواب لا تُفتح إلا لتريك ما لا ينبغي أن يُرى، وبعض الفرص تعدنا بالأمل.. وتُخفي في باطنها العذاب.\n«تحليق إيكاروس» ليست مجرّد رواية عادية، بل عمل سيترك في قلبك ندبةً لا تُرى.",
                            ImageUrl = "/images/products/9789778203257.webp",
