                        new
                        {
                            Id = 24,
                            Author = "طاهرة ماڤي",
                            CategoryId = 4,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "نغوص مع وارنر وكينجي في بحر من المشاعر الجياشة والتفاني المطلق، بينما يواجهان سباقًا مع الزمن لإنقاذ جولييت والحفاظ على حياتها. تدخل جولييت في غيبوبة غامضة، تاركة خلفها فراغًا ثقيلًا يدفع وارنر وكينجي إلى مواجهة قرارات مصيرية.\n\nفي الوقت نفسه، يتصاعد التوتر مع احتجاز أندرسون لجيمس وآدم وبقية أطفال القادة العُليا كرهائن، ما يجعل التحديات أكثر تعقيدًا وخطورة. يزخر هذا الجزء بالمنعطفات المدهشة والأحداث غير المتوقعة التي تطرح أسئلة ملحّة: هل ستنجو جولييت؟ وكيف سيتمكن أصدقاؤها من تحرير الرهائن ومواجهة أندرسون؟ والأهم… هل سينجحون في الإطاحة بنظام «إعادة التأسيس» إلى الأبد؟",
