                        new
                        {
                            Id = 31,
                            Author = "چورچ ر.ر مارتن",
                            CategoryId = 2,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "ما زالت حرب الملوك الخمسة مشتعلةً، تعاني ويلاتها جميع أنحاء الممالك السبع إلا قليلًا. على العرش الحديدي يجلس الملك الصبي الغاشم جوفري، فيما يسعى جدّه اللورد تايوين لانستر، يدُ الملك، لتأمين حكمه، ومن ثم تأمين السلطة لعائلة لانستر، مخططًا للقضاء على الملك ستانيس باراثيون الذي خرج مدحورًا من معركة الماء الأسود، وعلى الذئب الصغير روب ستارك الذي يقود حملةً في غرب البلاد رغم أنه فقد وطنه في الشمال.\n\nوفي تلك الأثناء تشقّ الملكة المنفية دينيرس تارجاريَن طريقها في قارّةٍ أخرى تُغرقها الدماء، بغية تحرير مئات الآلاف من العبيد والحصول على جيشٍ تستعيد به مملكتها، ومعها التنانين الثلاثة الحيّة الوحيدة في العالم.\n\nوفي الشمال يتحرّك جيشٌ جرّار من الهمج استعدادًا للهجوم على الجدار وغزو الممالك السبع، جيشٌ انضمّ إليه رجل حرس الليل جون سنو جاسوسًا، ولو أنّ شيئًا أسوأ منه يتقدّم من أقصى الشمال، العدوّ الحقيقي الذي ينشغل عنه الجميع تقريبًا بقتالهم، وقد لا تقدر جيوش الأرض كلّها على ردعه.",
