                        new
                        {
                            Id = 38,
                            Author = "مصطفى قمري",
                            CategoryId = 7,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "منذ أكثر من ثلاثة آلاف عام، وفي إحدى قرى مصر، توارث الناس حكايات عن مدينة كاملة اختفت من كتب التاريخ، مدينة عاشت زمن الاضطراب الذي شهدته البلاد في عهد الملك رمسيس الثالث، حين اجتاحت قبائل أجنبية تُدعى المشوش أطراف مصر، ونشرت الخراب والفساد بين القرى والبلدان، فذُبح رجال المدينة في معركة دامية، وتُركت نساؤها وحدهن في مواجهة الخوف والجوع والمجهول؛ لم يكنّ ملكات ولا أميرات، بل نساءً عاديات، منهن من حاولت النجاة بالفرار، ومنهن من أشعلت ثورة الجياع، ومن تشبثت بالسحر بحثًا عن طوق نجاة أخير.\n\nمملكة النساء ليست أسطورة، بل رواية مستوحاة من حكايات حقيقية ما زال أهل القرية يروونها حتى اليوم، رغم أنها لم تُذكر في أي كتاب تاريخي، رواية عن الصمود، وعن نساء واجهن وحدهن زمن الانهيار، وكتبن حكاياتهن، ثم اختفين من التاريخ.",
