                        new
                        {
                            Id = 47,
                            Author = "محمد مصطفي منصور",
                            CategoryId = 8,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "هذا الكتاب يُقدِّم للقارئ أشعار ابن عطاء الله السكندري، الذي عاش في القرن السابع الهجري، وتوفي مطلع القرن الثامن، وكانت أشعاره مُتفرِّقة في بعض كتبه.\nويجمع الكتاب شِعر «ابن عطاء» على وجهٍ ملائمٍ يليق بصاحب الشِّعر ومكانته، وبالأفكار التي اشتمل عليها، وبالقضايا التي يعالجها.\nوقد اجتهد مُحقِّق الكتاب في جمع شعر «ابن عطاء» من الأصول المخطوطة لبعض كتبه؛ للوقوف على حقيقة ما ورد بها من شِعر، وملابسات كل نَصٍّ منه، والتمكُّن من تحقيق تلك النصوص تحقيقًا علميًّا دقيقًا، وفق قواعد التحقيق العلمية، وضبط ألفاظ تلك النصوص، حتى تظهر الأشعار للقارئ بصورة جيدة، واستبعد المحقق الطبعات المتاحة بالأسواق لكتب «ابن عطاء» لكثرة ما ورد بها من أخطاء وتحريفات تحول بين القارئ للشعر وبين إدراك ما ورد به من أفكار بصورة صحيحة.\nوالكتاب إضافة حقيقية للمكتبة العربية، خاصة الأدب الصوفي المصري؛ إذ إنه يُعدُّ أول ديوانٍ مُحقَّقٍ لشِعر ابن عطاء الله السكندري.\n***\nد. محمد مصطفى منصور، أستاذ الأدب العربي المتفرغ بكلية دار العلوم، جامعة الفيوم. عمل محررًا وباحثًا بمجمع اللغة العربية بالقاهرة في الفترة من 1983م حتى 1991م، وشارك في تحرير مجالس المجمع ومؤتمره ومجلته. وضع الأسس الفنية لدراسة ملامح الأدب الصوفي المصري في كلية دار العلوم بجامعة الفيوم. أصدر نحو تسعة عشر كتابًا، منها: نداء المؤمنين في القرآن الكريم (1998م)، النثر الفني في عصري صدر الإسلام وبني أمية (1998م)، شرح قصيدة أبي مدين «ما لذة العيش إلا صحبة الفقرا» لابن عطاء الله السكندري (2001م)، الوقاية من العنف: قراءة تحليلية في الحديث النبوي الشريف (2021م).",
                            ImageUrl = "/images/products/9789777955935.webp",
                            Isbn = "9789777955935",
                            Name = "ديوان ابن عطاء",
                            Price = 175m,
                            PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc),
                            Stock = 10,
