                        new
                        {
                            Id = 48,
                            Author = "مصطفي الفقي",
                            CategoryId = 7,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "ليس سهلًا أن يعترف الإنسان بأخطائه أو سلبيات حياته، خاصة حين يكون قد حقَّق ما يضعه في مصاف المشهورين والمؤثرين في الحياة، وأضحى ملء السمع والبصر كما يُقال؛ لذلك فمجرد «التفكير» يُعد شجاعة كبيرة، أما الانتقال من منطقة الفكرة، إلى مساحة الفعل والكتابة، فهي جسارة لم يتَّسِم بها سوى قليلين.. ومن هؤلاء الجسورين الدكتور مصطفى الفقي، المفكر والكاتب والأديب والدبلوماسي والسياسي الذي طبَّقت شهرته الآفاق، ولم يكُن متحدثًا حصيفًا وراصدًا دقيقًا للأحداث فحسب، بل كثيرًا ما شارك في صناعتها، وحرَّك بفكره ورؤاه الكثير منها.\nوفي هذا الكتاب يقدم د. الفقي مادة ثرية كثراء حياته، ممتعة كطلاقة لسانه وتفرُّد أفكاره، متنوعة كتنوع خبراته وتشعُّب علاقاته، فيجد القارئ نفسه في بُستانٍ مُبهج، يتنقَّل فيه بسلاسةٍ ورشاقةٍ من الدبلوماسية إلى العمل الأكاديمي، ومن النشاط الإعلامي إلى التمثيل البرلماني، ومن الحياة الإنسانية البسيطة إلى الحياة السياسية المعقدة، فضلًا عن تناول كثير من القضايا الفكرية والإنسانية والثقافية والسياسية في مصر والوطن العربي بل والعالم، وككل كتب الدكتور مصطفى الفقي، فإن القارئ على موعد مع فيض فكري وإنساني، يمتاز برشاقة الأسلوب، وتنوع الأفكار، وبراعة الطرح والتناول.",
                            ImageUrl = "/images/products/9789777955898.webp",
                            Isbn = "9789777955898",
                            Name = "صفحات مطوية اعترافات ومراجعات",
                            Price = 400m,
                            PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc),
                            Stock = 10,
                            TopRated = false
                        },
                        new
                        {
                            Id = 49,
                            Author = "جو كالاجان",
                            CategoryId = 1,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "ماذا لو كان شريكك في التحقيق… ليس إنسانًا؟\nفي تجربة حكومية غير مسبوقة، تُجبر رئيسة المباحث «كات فرانك» على العمل مع «لوك»، ذكاء اصطناعي تجريبي بهيئة بشرية، لاختبار مستقبل العمل الشرطي، وذلك أثناء التحقيق في سلسلة من حالات الاختفاء الغامضة.\n«كات» تعتمد على الحدس والخبرة الإنسانية، و«لوك» لا يثق إلا في الأرقام والخوارزميات.\nلكن هذه القضية ليست عادية؛ كاميرات مراقبة متوقفة، آثار رقمية ممحوّة، وملفات بلا أي خيط واضح.\nهل هناك مَن يتلاعب بكل ما هو رقمي.. بلا أثر؟\nبينما تتقدم التحقيقات، تكتشف «كات» أن هناك قاسمًا مشتركًا واحدًا بين جميع المفقودين، قاسمًا لا تراه الخوارزميات، لكن يلتقطه حدسها فورًا: ابنها «كام».\nوعندما يختفي «كام» بدوره، يتحول التحقيق إلى سباق مع الزمن، وإلى مواجهة شخصية مع الماضي، ومع سؤال أخطر: هل يمكن للذكاء الاصطناعي أن يفهم الإنسان عندما تصبح حياته على المحك؟\n«في غمضة عين» رواية مشوقة تمزج بين الجريمة والخيال العلمي، عن الفقد والأمومة، وعن صراع الذكاء البشري مع الذكاء الاصطناعي، وعن ذلك الحد الفاصل الدقيق بين العبقرية.. والجنون.\nعن المؤلفة:\nجو كالاجان كاتبة بريطانية من برمنغهام، عملت لسنوات في مجالات القيادة والإدارة العامة، وبالتوازي اهتمت بأسئلة المستقبل وتأثير الذكاء الاصطناعي على المجتمع والعمل وهو ما ينعكس بوضوح في عالم روايتها. في عام 2024 فازت \"في غمضة عين\" بجائزة Theakston Old Peculier – Crime Novel of the Year (أفضل رواية جريمة في بريطانيا)، كما حصدت أيضًا جائزة CWA John Creasey (New Blood) Dagger لعام 2024، ووصلت إلى قوائم الترشيح لجوائز أخرى، لتصبح واحدة من أبرز الروايات البوليسية في السنوات الأخيرة.\nترجمة   :- حسام شاكر",
