                        new
                        {
                            Id = 61,
                            Author = "يوسف عز الدين عيسى",
                            CategoryId = 1,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "\"هدأت نفسه قليلًا، ولكنه عاد يشعر بقسوة الوحدة عندما قام الرجل واختفى داخل الكهف. ملأت السعادة قلبه عندما نظر فرأى على مقربة من الكهف مدينة ذات عمائر وقصور وقلاع. ظل ناظرًا إليها مبهورًا.\nلم تكن هذه المدينة هنا، فكيف ظهرت بغتة؟ أنا لم أتحرك من مكاني، فهل كانت المدينة تسير نحوي؟ هذا مستحيل. ماذا حدث إذن؟\".\n***\nتنتمي هذه المجموعة القصصية إلى العالم الأسطوري الحالم، الذي يبدأ بحدث واقعي مدهش، وينتهي بنا إلى نهايات غير متوقعة، فيضفي على كل ما هو واقعي سحرًا خاصًّا ورمزية غاية في التشويق.\nفقصص مثل: \"نور الشفق، القطار، ليلة العاصفة\"، تعبر عن النفس البشرية بكل أحلامها وإخفاقاتها وضآلة الإنسان بالنسبة لأسرار الكون، مهما أوتي من علم. أما \"الجمجمة\" -التي لم تنشر من قبل- فيجمع فيها د. يوسف عز الدين عيسى بين الأمراض النفسية وتأثيرها على الجسد.\nد. يوسف عز الدين عيسى، جمع بين العلم والأدب في أعلى مستوياتهما، فهو أديب له عالمه الخاص، حصل على جائزة الدولة التقديرية في الأدب وغيرها من الأوسمة الرفيعة. تأثر أدبه بروح العصر فعبر عن الإنسان وحلل النفس  البشرية بكل نوازعها وأحلامها وصراعاتها بأسلوب شيق يتأرجح بين الحلم والواقع، الخيال والحقيقة. كسرت رواياته الحاجز التقليدي للرواية العربية، وهو من أول رواد الواقعية السحرية فيها.",
                            ImageUrl = "/images/products/9789777955812.webp",
