                            Id = 64,
                            Author = "شريف عرفة",
                            CategoryId = 1,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "ليس كل صوت يُسمع.\nكل ما أراده (جلال) هو معرفة من يخاطبه، ولم يدرِ أن الطريق إليه يمر عبر طقوس دموية، وعوالم افتراضية، وطائفة دينية، وكيانات واعية.. وسط أحوال تذوب فيها الفواصل بين اليقين والوهم، وبين البشر ومن هم غير ذلك.\nرواية تتتبع رحلة عقل إلى حدوده القصوى..\nحيث الجواب موجود.. لكنه ينتظرك في مكان غير موجود.\nد. شريف عرفة\nالكاتب الأكثر مبيعًا في علم النفس الإيجابي.\nحاصل على ماجستير علم النفس الإيجابي التطبيقي، وماجستير\nفي إدارة الأعمال، وبكالوريوس طب وجراحة الأسنان.\nتُرجمت مؤلفاته للإنجليزية وحاز جوائز وتكريمات عديدة.",
