                        new
                        {
                            Id = 69,
                            Author = "زينب عفيفي",
                            CategoryId = 1,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "\" بعض الكلمات تظل عالقة في ذهني، وحين أكتب تعليقًا على رواية أعجبت ببطلها يأتي ناقصًا في المعنى، ولا تأتي مشاعري كما أشتهي، ويبقى إحساسي ناقصًا يحتاج إلى أن يخرج بطل الرواية عن النص ويضمني بالمعنى الناقص في واقعي\".\n***\n\"السماء لا تمطر حكايات\".. رواية عن امرأة تكتشف أن الكلمة قد تُسرق، لكن الروح لا تُنتزع.\nفي عالمٍ يُكافأ فيه مَن يتحدث بصوتٍ أعلى، تبقى \"حنان\" مجرد ظل في حياة الأدب. تكتب، وتحلم بنشر روايتها الأولى.. حتى تأتي الخيانة من أقرب الناس إلى روحها: مَن أحبَّته واعتقدت أنه الوحيد الذي يؤمن بأنها كاتبة. تستيقظ على كابوس نشر روايتها الأولى باسمه، وتتحول من \"كاتبة حالمة\" إلى \"ملهمة مجهولة\".\nتقف \"حنان\" أمام قرار مصيري: هل تستعيد أفكارها؟ أم تستعيد نفسها؟ أم تمتهن بيع الأفكار للروائيين المفلسين.\nزينب عفيفي.. كاتبة وروائية، صدر لها ثمانية عشر عملًا ما بين قصص قصيرة وكتب وروايات منها: \"شمس تشرق مرتين\" و\"خمس دقائق\" و\"أهداني حبًّا\" و\"أحلم وأنا بجوارك\" و\"معك تكتمل صورتي\"، و\"عزيزي المستبد\"، و\"عملية تجميل\".. تُرجمت بعض قصصها إلى اللغة الإنجليزية عن دار نشر أسترالية وبعضها تُرجم إلى اللغة الإيطالية. لها العديد من المقالات الأسبوعية في الأدب والثقافة. حازت جائزة أفضل صفحة في مجال الكتب في الصحافة الثقافية المصرية عام 2015م. حصلت على جائزة يوسف إدريس في دراسة بحثية نقدية عن أدبه.",
