                        new
                        {
                            Id = 70,
                            Author = "عزت القمحاوي",
                            CategoryId = 1,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "إننا، ببساطة مدهشة آسرة، أمام موت معلن منذ الصفحات الأولى، ندرك في الآن ذاته أنه مجازات حياة لا تقل احتشادًا بالصخب والكتمان والغرام.\nصبحي حديدي - من كلمته على غلاف \"غرفة ترى النيل\" 2004.\nيقدم لنا القمحاوي في \"البحر خلف الستائر\" تنويعاته المتفردة على ما سميته بتجربة الخروج العربي. وهي تجربة ثرية في الأدب المصري.\nصبري حافظ عن «البحر خلف الستائر» جريدة التحرير 2014.\nبخفة الثعبان الذي يخاف ويخيف ـ يستعير القمحاوي لغة المدينة ليواجهها بأقوالها وأساطيرها نازعًا عنها عباءتها التي لا تستر عورة.\nعبدالرحمن الأبنودي ـ عن «مدينة اللذة» في كتابه النثري «آخر الليل».\n“مدينة اللذة”، عمل فذ، وعلامة فارقة في فن القص العربي. نص بالغ الدقة والإحكام والحساسية.\nفتحي أبو رفيعة ـ من كتابه «تفكيك السرد».\nمن اليأس تأتي هذه الكتابة. كل لذة يجب أن تؤخذ ضمن حدود اللحظة. كل جمال في حقيقته سراب..\nعناية جابر ـ عن مدينة اللذة، جريدة السفير 2009.",
                            ImageUrl = "/images/products/9789777955607.webp",
                            Isbn = "9789777955607",
