                        new
                        {
                            Id = 80,
                            Author = "إبراهيم عبد المجيد",
                            CategoryId = 8,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "هذا كتاب جديد لإبراهيم عبد المجيد يضم مجموعة من المقالات والدراسات الهامة التي نُشرت في صحف شهيرة بين عامي 2025-2024م. تدور حول قضايا الإنسان في العالم، والأوضاع الإنسانية في تجلياتها السياسية والاجتماعية والثقافية، وقضايا فلسفية عابرة للزمن. وكالعادة ضم إليها مراجعات لكتب هامَّة لعدد من أهم الكُتَّاب والأدباء والمفكرين من كل الأعمار. هكذا ستجد نفسك أثناء القراءة مستمتعًا برحلة فكرية وإنسانية دافقة بالمحبة، ستأخذك إلى فضاء من الجمال والأمل.\nإبراهيم عبد المجيد، كاتب وروائي مصري، له أكثر من 25 رواية، منها: ثلاثية الإسكندرية، و\"في كل أسبوع يوم جمعة\"، و\"أداجيو\"، و\"بيت الياسمين\"، و\"البلدة الأخرى\"، عرف بعضها الطريق إلى السينما والتلفزيون. له خمس مجموعات قصصية، وأكثر من خمسة عشر كتابًا بين الدراسات والمقالات والترجمة. تُرجمت بعض أعماله إلى الإنجليزية والفرنسية وغيرهما، وحاز أرقى الجوائز مثل: جائزة الشيخ زايد بالإمارات، وجائزة كتارا بقطر، وجائزة النيل بمصر.",
