                        new
                        {
                            Id = 81,
                            Author = "جمال سند السويدي",
                            CategoryId = 8,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "تزايد الاهتمام الإعلامي والعلمي بالرحم الاصطناعي في السنوات القليلة الماضية على مستوى العالم، ولا سيما مع التقدم السريع الذي تحرزه البحوث، التي تجرى في كثير من الدول، مــن الصين واليابان شرقا، إلى أوروبا وأمريكا الشمالية غرباء لاستكشاف و اختبار إمكانية حدوث حمل كامل خارج الجسد؛ أي خارج الرحم الطبيعي. وعلى الرغم من أن بحوث الرحم الاصطناعي لا تزال في مرحلة باكرة إلى حد ما، وتُجرى على الحيوانات؛ ومقيدة بقواعد أخلاقيات العلم والبحوث المتفق عليها؛ فإن التقدم المتسارع المذهل، الذي يتحقق في تلك البحوث، التي تتضافر فيها حقول معرفية وبحثية عدة خاصة الذكاء الاصطناعي والتقنية، أطلق العنان لخيال البشر للتفكير في لحظة سيتمكن فيها الإنسان من التحكم بعملية الحمل؛ لتتحقق كاملة خارج جسم الإنسان؛ وتبشر بمرحلة للتكاثر ما بعد البشري، خاصة أن تلك البحوث تستفيد من التقدم المتسارع في تقنية المعلومات، والذكاء الاصطناعي وتطبيقاته، والتطور المذهل في تصنيع الروبوتات، والتقنية المتناهية الصغر (النانو تكنولوجي)، والاندماج المتزايد بين علم الأحياء\n(البيولوجي) وعلم الحاسوب. وتكفي إطلالة سريعة على التقارير الصحفية في وسائل الإعلام بشتى اللغات؛ للوقوف على الآفاق التي وصل إليها خيال البشر؛ ومقارنتها بالحالة الفعلية الراهنة للبحوث في مجال الرحم الاصطناعي؛ إذ تنقل تقارير منشورة تقديرات للعلماء، تشير إلى أن إمكانية تطوير رحم اصطناعي، خلال الفترة المقبلة، تسهم في إنقاذ الأطفال الخدج، المولودين قبل إتمام 37 أسبوعًا في رحم الأم وهذا هو السبب الرئيسي للوفاة بين حديثي الولادة في العالم ؛ وهذا التطور المحتمل يثير - برغم محدوديته مقارنة بما يذهب إليه الخيال - تساؤلات أخلاقية بشأن مستقبل ولادة الأطفال .\nجمال سند السويدي\nمفكر وكاتب وخبير استراتيجي إماراتي، شغل منصب مدير عام مركز الإمارات للدراسات والبحوث الاستراتيجية منذ عام 1994 حتى عام 2020. ويشغل حالياً منصب نائب رئيس مجلس أمناء مركز الإمارات للدراسات والبحوث الاستراتيجية.\nشارك في عدد من المجالس الاستشارية والعلمية والتنفيذية المرموقة بصفة عضو أو رئيس، وحصل على العديد من الجوائز المحلية والدولية. تقديراً لإسهاماته وجهوده العلمية، منها جائزة الشيخ زايد للكتاب» في 1 مايو 2016، وجائزة نجيب محفوظ للآداب في 8 إبريل 2016، ولقب سفير السلام من اتحاد السلام العالمي في 21 مارس 2017 تقديراً لجهوده الكبيرة والمتواصلة في العمل على نشر ثقافة التسامح والوسطية.\nألف أكثر من 35 كتاباً من مختلف الأدبيات السياسية والاجتماعية أحدثها كتاب «الهوية الوطنية في دولة الإمارات العربية المتحدة.. بين خصوصية الثوابت والقيم وعالمية المعايير، وكتاب صاحب السمو الشيخ محمد بن زايد آل نهيان.... إضاءات في مسيرة رجل الإنسانية». وأعد وحزر عدداً آخر من الكتب القيمة، أبرزها كتاب حرب اليمن .1994.. الأسباب والنتائج، وكتاب إيران والخليج.. البحث عن الاستقرار» وكتاب أمن الخليج في القرن الحادي والعشرين».",
