                        new
                        {
                            Id = 86,
                            Author = "اشرف العشماوي",
                            CategoryId = 1,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "تدور أحداث الرواية في مرحلةٍ بالغة الأهمية من تاريخ مصر المعاصر، من خلال موظف في إدارة المراسم عمل لسنوات بمعيّة الرئيسين السادات ومبارك ، فاقترب بما يكفي ليصبح شاهدًا على كواليس عصرٍ كامل؛ تكشف الرواية في واقعيةٍ مشوّقة عن مرحلة الانتقال من دهاليز المراسم إلى أروقة السلطة.. حيث تُدار الأمور في صمتٍ مُحكم، وتُحاك المؤامرات بدهاء. هذه الرواية عن إنسان عادي حين تفتك به سلطة المناصب، وتمزّقه التناقضات ويظلله الخوف. وبين قسوةٍ تربّى عليها منذ طفولته، ورقّة الموسيقى التي يُجيد عزفها على آلة الكمان، يحاول أن يجد خلاصه؛ لكن كل نغمةٍ يعزفها تغدو مِرآةً لجراحه ومرثية لأحلامه، وكل لحنٍ يؤلفه يتحوّل إلى قناعٍ يخفي وراءه خوفه العميق. \"السيمفونية الأخيرة \" رحلة تأملية جريئة إلى أعماق النفس البشرية، تضع القارىء منذ المفتتح في التجربة بكل تناقضاتها، ثم تتركه معلقًا بين الحقيقة والخيال في سيمفونية لا تنتهي من كشف الأسرار وتبدل المصائر .\nأشرف العشماوي روائي وقاضٍ مصري، نُشرت له اثنتا عشرة رواية طويلة، وكتابٌ وثائقيٌّ عن الآثار المصرية المُهربة للخارج ومحاولات استعادتها بعنوان \"سرقات مشروعة\"، وثلاث نوفيلات بعنوان \"مواليد حديقة الحيوان\". فاز بعدة جوائز محلية وعربية وعالمية، وتُرجمت أعماله إلى إحدى عشرة لغة أجنبية.",
