                            Author = "آمنة الغنيم",
                            CategoryId = 1,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "أربع بنات وأربع حكايات، ما بين دانة التي تعيش مع أشباح الماضي.\nولولوة التي تغلق نفسها على سرها، ونجلاء التي تجري وراء وهم الثراء، وصبا التي تعيش داخل سجن سلبيتها.\nنعيش حكايتهن، أوجاعهن، وأفراحهن، فهل تستحق السعادة أن نكسر حاجز خوفنا وسجن أفكارنا لتحلق في سمائها ؟\nآمنة الغنيم حاصلة على شهادة علم الاجتماع والخدمة الاجتماعية من جامعة الكويت عملت باحثة اجتماعية في دار الرعاية الأحداث، ومساعد علمي في جامعة الكويت صدر لها كتاب \"الحرملك\"، وتكتب في العديد من الصحف والمجلات الكويتية.",
