                        new
                        {
                            Id = 93,
                            Author = "طارق الطيب",
                            CategoryId = 1,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "\"سأقول لك شيئًا لا أعرف هل سيروق لك أم سيقلقك. يمكننا أن نجعلك تستمع لأدقّ أسرار الحياة السابقة وكلِّ ما مرّ حتّى يومنا هذا، لكن متى رغبت في مغادرتنا، فسنعملُ على محو كلّ المعلومات والأسرار التي عرفتها، وإلا...لن تتحمّل التنكيل الذي سيحيق بك\".\n***\nهناك على الناحية الأخرى من جسر الحياة، تقف الأبديَّةُ لتحرس سكونَ الأموات، من الآن لن يصبح العدم مخيفًا ومقبضًا.. هناك لا يلتقي الإنسان بناصره وغريمه فحسب، بل يلتقي أيضًا بنفسه، حيث ساحة \"البوح\" التي يتخفف فيها \"الضمير\" الإنساني مما يثقل روحه، لا أحد هناك يلوم الآخر على ما فعله في الحياة السابقة، فالأرواح تأتي نقيّة... في نهاية هذه الرواية \"ستشعر بعد خروجك أنّك غفوت قليلًا في مكان ما\"!\nطارق الطيب من مواليد القاهرة 1959. انتقل إلى فيينا عام 1984. له 20 كتابًا مترجمًا. حصل على وسام الجمهورية النمساوية في 2008، عُين سفيرًا ثقافيًا للنمسا في العام نفسه. صدر له مؤخرًا (ما يسبق الواو) و(لهو الإله الصغير).\nسنةالنشر :- 2025",
                            ImageUrl = "/images/products/9789777955218.webp",
